import openpyxl
import os

def solve():
    wb = openpyxl.load_workbook('/app/spreadsheets/1_22-47_input.xlsx')
    ws = wb.active

    # Identify headers from row 1 dynamically
    header_b = str(ws.cell(row=1, column=2).value).strip()
    header_c = str(ws.cell(row=1, column=3).value).strip()

    data = []
    for row_idx in range(2, ws.max_row + 1):
        item = ws.cell(row=row_idx, column=1).value
        name = ws.cell(row=row_idx, column=2).value
        ref = ws.cell(row=row_idx, column=3).value

        # Skip entirely empty cells in the row
        if (item is None or str(item).strip() == '') and \
           (name is None or str(name).strip() == '') and \
           (ref is None or str(ref).strip() == ''):
            continue

        # Skip headers
        if str(name).strip() == header_b and str(ref).strip() == header_c:
            continue

        if name is None or str(name).strip() == '':
            continue

        data.append({
            'item': item,
            'name': name,
            'ref': ref,
            'row_idx': row_idx
        })

    # Skip duplicates (identical in B and C)
    unique_data = []
    seen = set()
    for d in data:
        key = (str(d['name']).strip(), str(d['ref']).strip())
        if key not in seen:
            seen.add(key)
            unique_data.append(d)

    # Read column J
    list_j = []
    for row_idx in range(2, ws.max_row + 1):
        val = ws.cell(row=row_idx, column=10).value
        if val is not None and str(val).strip() != '':
            list_j.append(str(val).strip())

    if not list_j:
        unique_data.sort(key=lambda x: str(x['name']).strip())
    else:
        j_dict = {}
        for i, name in enumerate(list_j):
            if name not in j_dict:
                j_dict[name] = i

        def sort_key(x):
            name = str(x['name']).strip()
            if name in j_dict:
                return (0, j_dict[name], x['row_idx'])
            else:
                return (1, 0, x['row_idx'])
        unique_data.sort(key=sort_key)

    # Clear answer_position F2:H20
    for row_idx in range(2, 21):
        ws.cell(row=row_idx, column=6).value = None
        ws.cell(row=row_idx, column=7).value = None
        ws.cell(row=row_idx, column=8).value = None

    # Write output to F2:H20
    for i, d in enumerate(unique_data):
        row_idx = i + 2
        if row_idx > 20:
            break
        ws.cell(row=row_idx, column=6).value = d['item']
        ws.cell(row=row_idx, column=7).value = d['name']
        ws.cell(row=row_idx, column=8).value = d['ref']

    os.makedirs('/app/output', exist_ok=True)
    wb.save('/app/output/1_22-47_output.xlsx')
    print("Final solution saved successfully.")

if __name__ == '__main__':
    solve()
